param(
    [Parameter(Mandatory = $true)][string]$OutFile
)

$ErrorActionPreference = 'Stop'

$exactIds = @(
    'USB\VID_1366&PID_1025\000683854191',   # NRF-B
    'USB\VID_1366&PID_1025\000683710208',   # NRF-A
    'USB\VID_0483&PID_374B\0668FF514988525067213913', # STM-B
    'USB\VID_0483&PID_374B\066FFF514988525067233337'  # STM-A
)

$result = [ordered]@{
    captured_at_utc = (Get-Date).ToUniversalTime().ToString('o')
    exact_composite_ids = $exactIds
    composites = @()
    com_ports = @()
}

foreach ($id in $exactIds) {
    $dev = Get-PnpDevice -InstanceId $id -ErrorAction SilentlyContinue
    $locProp = $null
    if ($dev) {
        $locProp = (Get-PnpDeviceProperty -InstanceId $id -KeyName 'DEVPKEY_Device_LocationPaths' -ErrorAction SilentlyContinue).Data
    }
    $result.composites += [ordered]@{
        instance_id = $id
        present = [bool]$dev
        status = if ($dev) { $dev.Status } else { $null }
        friendly_name = if ($dev) { $dev.FriendlyName } else { $null }
        location_paths = if ($locProp) { @($locProp) } else { @() }
    }
}

# COM port snapshot: every present COM port, its InstanceId, and whether it is a child of one of the four exact composites
$ports = Get-PnpDevice -Class Ports -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.FriendlyName -match 'COM\d+' }
foreach ($p in $ports) {
    $parent = Get-PnpDeviceProperty -InstanceId $p.InstanceId -KeyName 'DEVPKEY_Device_Parent' -ErrorAction SilentlyContinue
    $parentId = if ($parent) { $parent.Data } else { $null }
    $comMatch = [regex]::Match($p.FriendlyName, '\((COM\d+)\)')
    $com = if ($comMatch.Success) { $comMatch.Groups[1].Value } else { $null }
    $result.com_ports += [ordered]@{
        instance_id = $p.InstanceId
        com = $com
        friendly_name = $p.FriendlyName
        parent_instance_id = $parentId
        parent_is_exact_composite = ($exactIds -contains $parentId)
    }
}

$result | ConvertTo-Json -Depth 6 | Set-Content -Path $OutFile -Encoding UTF8
Write-Output "Wrote $OutFile"

