param(
    [Parameter(Mandatory = $true)][string]$OutFile
)

$ErrorActionPreference = 'Stop'

# Exact composite InstanceIds from USB_REENUM_ASSIGNMENT.md, serial order as listed
$exactIds = @(
    'USB\VID_1366&PID_1025\000683854191',   # NRF-B
    'USB\VID_1366&PID_1025\000683710208',   # NRF-A
    'USB\VID_0483&PID_374B\0668FF514988525067213913', # STM-B
    'USB\VID_0483&PID_374B\066FFF514988525067233337'  # STM-A
)

$waitSeconds = 30
$results = @()

foreach ($id in $exactIds) {
    $entry = [ordered]@{
        instance_id = $id
        started_utc = (Get-Date).ToUniversalTime().ToString('o')
        disable_ok = $false
        disable_error = $null
        enable_ok = $false
        enable_error = $null
        returned_within_bound = $false
        return_wait_seconds = $null
        present_after = $false
        status_after = $null
        location_paths_after = @()
        vcom_after = $null
        vcom_parent_ok = $false
    }

    # 1. Disable exact device
    try {
        Disable-PnpDevice -InstanceId $id -Confirm:$false -ErrorAction Stop | Out-Null
        $entry.disable_ok = $true
    } catch {
        $entry.disable_error = $_.Exception.Message
    }

    # 2. Enable exact device
    if ($entry.disable_ok) {
        try {
            Enable-PnpDevice -InstanceId $id -Confirm:$false -ErrorAction Stop | Out-Null
            $entry.enable_ok = $true
        } catch {
            $entry.enable_error = $_.Exception.Message
        }
    }

    # 3. Wait up to 30s for exact identity + its VCOM to return
    if ($entry.enable_ok) {
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $vcom = $null
        while ($sw.Elapsed.TotalSeconds -lt $waitSeconds) {
            $dev = Get-PnpDevice -InstanceId $id -ErrorAction SilentlyContinue
            if ($dev -and $dev.Status -eq 'OK') {
                # find child COM port
                $ports = Get-PnpDevice -Class Ports -PresentOnly -ErrorAction SilentlyContinue
                foreach ($p in $ports) {
                    $parent = Get-PnpDeviceProperty -InstanceId $p.InstanceId -KeyName 'DEVPKEY_Device_Parent' -ErrorAction SilentlyContinue
                    if ($parent -and $parent.Data -eq $id) {
                        $comMatch = [regex]::Match($p.FriendlyName, '\((COM\d+)\)')
                        if ($comMatch.Success) { $vcom = $comMatch.Groups[1].Value }
                        break
                    }
                }
                if ($vcom) { break }
            }
            Start-Sleep -Milliseconds 500
        }
        $sw.Stop()
        $entry.return_wait_seconds = [math]::Round($sw.Elapsed.TotalSeconds, 2)
        $entry.returned_within_bound = ($sw.Elapsed.TotalSeconds -lt $waitSeconds) -and [bool]$vcom
        $entry.vcom_after = $vcom
        $entry.vcom_parent_ok = [bool]$vcom
    }

    # 4. Final observed state
    $devAfter = Get-PnpDevice -InstanceId $id -ErrorAction SilentlyContinue
    $entry.present_after = [bool]$devAfter
    $entry.status_after = if ($devAfter) { $devAfter.Status } else { $null }
    if ($devAfter) {
        $locProp = (Get-PnpDeviceProperty -InstanceId $id -KeyName 'DEVPKEY_Device_LocationPaths' -ErrorAction SilentlyContinue).Data
        $entry.location_paths_after = if ($locProp) { @($locProp) } else { @() }
    }
    $entry.ended_utc = (Get-Date).ToUniversalTime().ToString('o')

    $results += $entry
}

$out = [ordered]@{
    captured_at_utc = (Get-Date).ToUniversalTime().ToString('o')
    wait_bound_seconds = $waitSeconds
    method = 'Disable-PnpDevice -Confirm:$false then Enable-PnpDevice -Confirm:$false, exact InstanceId only, serial, one at a time'
    devices = $results
}
$out | ConvertTo-Json -Depth 6 | Set-Content -Path $OutFile -Encoding UTF8
Write-Output "Wrote $OutFile"

